diff --git a/src/api/common/utils/EntityUtils.ts b/src/api/common/utils/EntityUtils.ts
index 95c62f218..98f28fef9 100644
--- a/src/api/common/utils/EntityUtils.ts
+++ b/src/api/common/utils/EntityUtils.ts
@@ -334,3 +334,36 @@ export function assertIsEntity<T extends SomeEntity>(entity: SomeEntity, type: T
 export function assertIsEntity2<T extends SomeEntity>(type: TypeRef<T>): (entity: SomeEntity) => entity is T {
 	return (e): e is T => assertIsEntity(e, type)
 }
+
+/**
+ * Removes technical fields from an entity and all its nested objects.
+ * Technical fields are those that start with "_finalEncrypted".
+ * This function modifies the entity in-place.
+ * 
+ * @param entity The entity to clean
+ */
+export function removeTechnicalFields(entity: ElementEntity): void {
+	const removeFieldsRecursively = (obj: any): void => {
+		if (obj === null || typeof obj !== "object") {
+			return
+		}
+
+		// If it's an array, process each element
+		if (Array.isArray(obj)) {
+			obj.forEach(removeFieldsRecursively)
+			return
+		}
+
+		// For objects, iterate over keys and remove those starting with _finalEncrypted
+		for (const key of Object.keys(obj)) {
+			if (key.startsWith("_finalEncrypted")) {
+				delete obj[key]
+			} else if (obj[key] !== null && typeof obj[key] === "object") {
+				// Recursively process nested objects and arrays
+				removeFieldsRecursively(obj[key])
+			}
+		}
+	}
+
+	removeFieldsRecursively(entity)
+}
