+/**
+ * Enum for calendar event validity states
+ */
+export enum CalendarEventValidity {
+	Valid = "Valid",
+	InvalidPre1970 = "InvalidPre1970",
+	InvalidEndBeforeStart = "InvalidEndBeforeStart",
+	InvalidDateValue = "InvalidDateValue",
+}
+
+/**
+ * Check if a calendar event has valid dates
+ * @param event The calendar event to validate
+ * @returns The validity status of the event
+ */
+export function checkEventValidity(event: CalendarEvent): CalendarEventValidity {
+	// Check for invalid date values (NaN)
+	if (!isValidDate(event.startTime) || !isValidDate(event.endTime)) {
+		return CalendarEventValidity.InvalidDateValue
+	}
+
+	// Check for pre-1970 start dates
+	if (event.startTime.getFullYear() < 1970) {
+		return CalendarEventValidity.InvalidPre1970
+	}
+
+	// Check if end date is before or equal to start date
+	if (event.endTime.getTime() <= event.startTime.getTime()) {
+		return CalendarEventValidity.InvalidEndBeforeStart
+	}
+
+	return CalendarEventValidity.Valid
+}
